/** managerrequest-mapper.getManagerRequestList (관리자 신청 목록 조회) */ SELECT A.USER_ID ,A.REQST_SN ,LOGIN_ID AS LOGIN_ID ,A.LOCGOV_CODE ,A.REQST_SE_CODE ,A.PSITN_CODE ,A.PSITN_NM ,A.PSITN_DEPT_NM ,OFCPS_NM AS FCPS_NM ,CTTPC AS CTTPC ,A.CONFM_STTUS_CODE ,A.REJECT_RESN ,A.FRST_REGISTER_ID ,A.FRST_REGIST_PNTTM ,A.LAST_UPDUSR_ID ,A.LAST_UPDT_PNTTM FROM ( SELECT R.USER_ID, R.REQST_SN, R.LOGIN_ID, R.LOCGOV_CODE, R.REQST_SE_CODE, R.PSITN_CODE, R.PSITN_NM, R.PSITN_DEPT_NM, R.OFCPS_NM, R.CTTPC, R.CONFM_STTUS_CODE, R.REJECT_RESN, R.FRST_REGISTER_ID, R.FRST_REGIST_PNTTM, R.LAST_UPDUSR_ID, R.LAST_UPDT_PNTTM FROM G_MNGR_REQST R
AND R.USER_ID = #{userId}
AND R.REQST_SN= #{reqstSn}
AND R.LOGIN_ID= #{loginId}
AND R.LOCGOV_CODE = #{locgovCode}
AND R.REQST_SE_CODE = #{reqstSeCode}
AND R.CONFM_STTUS_CODE = #{confmSttusCode}
) A

/** managerrequest-mapper.getManagerRequestListByParam (관리자 권한 승인관리 목록 조회) */ SELECT A.USER_ID ,A.REQST_SN ,A.LOGIN_ID AS LOGIN_ID ,A.LOCGOV_CODE ,A.REQST_SE_CODE ,A.PSITN_CODE ,A.PSITN_NM ,A.PSITN_DEPT_NM ,A.OFCPS_NM AS OFCPS_NM ,A.CTTPC AS CTTPC ,A.CONFM_STTUS_CODE ,A.REJECT_RESN ,A.FRST_REGISTER_ID ,DATE_FORMAT(A.FRST_REGIST_PNTTM,'%Y-%m-%d') AS FRST_REGIST_PNTTM ,A.LAST_UPDUSR_ID ,DATE_FORMAT(A.LAST_UPDT_PNTTM,'%Y-%m-%d') AS LAST_UPDT_PNTTM ,A.USER_NAME AS USER_NAME ,A.EMAIL AS EMAIL ,A.PHONE_NUMBER AS PHONE_NUMBER ,A.BIRTHDAY AS BIRTHDAY ,A.CONFM_STTUS_NM ,A.REQST_SE_NM ,A.LOCGOV_NM ,A.UPPER_LOCGOV_NM ,A.BANK_NM ,A.UPPER_LOCGOV_CODE FROM (
SELECT R.USER_ID, R.REQST_SN, R.LOGIN_ID, R.LOCGOV_CODE, R.REQST_SE_CODE, R.PSITN_CODE, R.PSITN_NM, R.PSITN_DEPT_NM, R.OFCPS_NM, R.CTTPC, R.CONFM_STTUS_CODE, R.REJECT_RESN, R.FRST_REGISTER_ID, R.FRST_REGIST_PNTTM, R.LAST_UPDUSR_ID, R.LAST_UPDT_PNTTM, U.USER_NAME, U.EMAIL, UD.PHONE_NUMBER, UD.BIRTHDAY, C1.LABEL AS CONFM_STTUS_NM, C2.LABEL AS REQST_SE_NM, C3.LABEL AS LOCGOV_NM, C4.LABEL AS UPPER_LOCGOV_NM, C5.LABEL AS BANK_NM, CONCAT(SUBSTR(R.LOCGOV_CODE, 1, 2), '000') AS UPPER_LOCGOV_CODE FROM G_MNGR_REQST R INNER JOIN OP_USER U ON U.USER_ID = R.USER_ID INNER JOIN OP_USER_DETAIL UD ON UD.USER_ID = U.USER_ID LEFT OUTER JOIN OP_COMMON_CODE C1 ON C1.CODE_TYPE = 'CFM_STATUS' AND C1.USE_YN = 'Y' AND C1.LANGUAGE = 'ko' AND C1.ID = R.CONFM_STTUS_CODE LEFT OUTER JOIN OP_COMMON_CODE C2 ON C2.CODE_TYPE = 'REQST_SE_CODE' AND C2.USE_YN = 'Y' AND C2.LANGUAGE = 'ko' AND C2.ID = R.REQST_SE_CODE LEFT OUTER JOIN OP_COMMON_CODE C3 ON C3.CODE_TYPE = 'LOCGOV_CODE' AND C3.USE_YN = 'Y' AND C3.LANGUAGE = 'ko' AND C3.ID = R.LOCGOV_CODE LEFT OUTER JOIN OP_COMMON_CODE C4 ON C4.CODE_TYPE = 'WDR' AND C4.USE_YN = 'Y' AND C4.LANGUAGE = 'ko' AND C4.ID = CONCAT(SUBSTR(R.LOCGOV_CODE, 1, 2), '000') LEFT OUTER JOIN OP_COMMON_CODE C5 ON C5.CODE_TYPE = 'OFF_BANK_LIST' AND C5.USE_YN = 'Y' AND C5.LANGUAGE = 'ko' AND C5.ID = R.PSITN_CODE
ORDER BY R.FRST_REGIST_PNTTM DESC
) A

