/** managerrequest-mapper.getManagerRequestDetailsAuthCount (관리자 권한 승인관리 상세 조회 접근 권한 체크) */
SELECT	COUNT(*)
FROM	G_MNGR_REQST R
WHERE	R.USER_ID = #{userId}
AND		R.REQST_SN = #{reqstSn}


	AND	R.REQST_SE_CODE = #{reqstSeCode}



	AND	R.LOCGOV_CODE = (SELECT LOCGOV_CODE FROM OP_MANAGER WHERE USER_ID = #{superUserId} AND STATUS_CODE = 9)

/** managerrequest-mapper.getUserStatusCodeByUserId (사용자 상태값 확인) */
SELECT STATUS_CODE
FROM OP_USER
WHERE USER_ID = #{value}

/** managerrequest-mapper.getNoticeList (관리자 공지사항 가져오기) */ SELECT MANAGER_NOTICE_ID ,SUBJECT ,CONTENT ,START_DATE ,END_DATE ,USE_YN ,WIDTH ,HEIGHT FROM OP_MANAGER_NOTICE WHERE USE_YN = 'Y' AND START_DATE <= DATE_FORMAT(now(), '%Y%m%d%H%m%s') AND END_DATE >= DATE_FORMAT(now(), '%Y%m%d%H%m%s')
AND NOTICE_TYPE IN('A', #{type})
AND NOTICE_TYPE = 'A'
